// A device-local place to rest between games.
state.cafe=Object.assign({seat:'window',drink:'latte',visits:0,lastDay:'',focusMinutes:0},state.cafe||{});
const cafeSeats=[['window','靠窗','🪟'],['bar','吧台','☕'],['corner','角落','📚']];
const cafeDrinks=[['americano','美式','☕'],['plainTea','茶','🍵'],['latte','拿鐵','☕'],['tea','奶茶','🧋'],['cocoa','熱可可','🍫'],['water','白開水','💧']];
function cafeGreeting(){const c=state.cafe,d=cafeDrinks.find(x=>x[0]===c.drink)[1];return c.visits>=3?'老王：'+d+'對吧？你的位子還在，今天慢慢來。':'阿電：歡迎，選個舒服的位置吧。今天不用急著開桌。'}
function openCafe(){openPanel('邊緣人咖啡廳','SOLO TOWN / CAFÉ');const c=state.cafe,day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei'}).format(new Date());if(c.lastDay!==day){c.lastDay=day;c.visits++;persist()}let remaining=25*60,running=false,deadline=0,interval=null;ui(`<div class="cafe-welcome"><span class="cafe-sign">☕ OPEN · 今天也有你的位子</span><h3>坐一下，再決定要做什麼。</h3><p id="cafeGreeting"></p><span id="cafeVisit"></span></div><section class="cafe-weather" id="cafeWeather"><strong id="cafeWeatherTitle">窗外天氣尚未設定</strong><p id="cafeWeatherStatus" role="status">使用目前位置，或搜尋你的城市。</p><div class="cafe-options"><button id="cafeLocate">使用目前位置</button><button id="cafeWeatherRefresh" disabled>更新天氣</button></div><form id="cafeCityForm"><label for="cafeCity">城市名稱</label><div class="cafe-city-search"><input id="cafeCity" placeholder="例如：淡水、台北、Tokyo" maxlength="80" required><button type="submit">搜尋</button></div></form><div id="cafeCityResults" class="cafe-options"></div><small>定位只在你點選後使用；約略座標會傳給 Open-Meteo 查天氣，不存入遊戲存檔。城市選擇會記在這台裝置。<br>天氣資料：<a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>（模型估計） · 城市：GeoNames</small></section><section class="cafe-section"><h3>選個座位</h3><div class="cafe-options" id="cafeSeats">${cafeSeats.map(s=>`<button data-seat="${s[0]}" aria-pressed="false">${s[2]} ${s[1]}</button>`).join('')}</div><h3>今天喝什麼？</h3><div class="cafe-options" id="cafeDrinks">${cafeDrinks.map(d=>`<button data-drink="${d[0]}" aria-pressed="false">${d[2]} ${d[1]}</button>`).join('')}</div><p class="cafe-note">虛擬飲料免費供應，不需要點數或付款。</p><div class="cafe-table"><strong id="cafeOrder"></strong><p id="cafeSeatText"></p></div></section><section class="cafe-section"><h3>今天想怎麼待？</h3><div class="cafe-options"><button data-mode="quiet" aria-pressed="true">安靜坐坐</button><button data-mode="chat" aria-pressed="false">找人聊聊</button><button data-mode="focus" aria-pressed="false">做自己的事</button></div><div id="cafeQuiet"><p>飲料放在手邊，今天可以什麼都不做。</p><label for="cafeSoundType">背景聲</label><select id="cafeSoundType">${cafeSounds.map(s=>`<option value="${s[0]}">${s[1]}</option>`).join('')}</select><div class="cafe-options"><button id="cafeSound">播放背景聲</button></div><small>合成環境聲 · 自由選擇，不會隨天氣自動播放。</small><label class="cafe-volume">音量 <input id="cafeVolume" type="range" min="0" max="0.15" step="0.005" value="0.04"></label><p id="cafeSoundStatus" role="status"></p></div><div id="cafeChat" hidden><label>誰坐過來？ <select id="cafeNPC"><option value="0">🤖 阿電</option><option value="1">😎 小花</option><option value="2">🧋 老王</option></select></label><div id="cafeConversation" class="cafe-conversation" aria-live="polite"></div><div class="cafe-options"><button data-topic="day">今天有點累</button><button data-topic="game">聊聊剛剛的遊戲</button><button data-topic="wish">今天想做什麼</button><button data-topic="story">熟客小故事</button></div><small>選個話題，看看 NPC 的小劇情。</small></div><div id="cafeFocus" hidden><label>這段時間 <select id="cafeDuration"><option value="25">25 分鐘</option><option value="10">10 分鐘</option><option value="45">45 分鐘</option></select></label><div id="cafeClock" class="cafe-clock" role="timer">25:00</div><p id="cafeFocusStatus" role="status">讀書、工作或休息，做你自己的事。</p><div class="cafe-options"><button id="cafeStart" class="primary">開始</button><button id="cafeReset">重設</button></div><small>離開咖啡廳會結束計時；背景分頁仍會計時。</small></div></section><div class="choices"><button id="cafeBack">回遊樂場</button></div>`);
function draw(){const seat=cafeSeats.find(s=>s[0]===c.seat),drink=cafeDrinks.find(d=>d[0]===c.drink);$('#cafeGreeting').textContent=cafeGreeting();$('#cafeVisit').textContent='來店 '+c.visits+' 天 · 完成專注 '+c.focusMinutes+' 分鐘';$('#cafeOrder').textContent=drink[2]+' '+drink[1]+'已上桌';$('#cafeSeatText').textContent={window:cafeWindowLine(),bar:'吧台留了一個位子，想說話時有人接。',corner:'這個角落安靜得剛剛好。'}[seat[0]];$('#cafeSeats').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.seat===c.seat)));$('#cafeDrinks').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.drink===c.drink)))}draw();const disposeWeather=setupCafeWeather(draw);$('#cafeSeats').querySelectorAll('button').forEach(b=>b.onclick=()=>{c.seat=b.dataset.seat;persist();draw()});$('#cafeDrinks').querySelectorAll('button').forEach(b=>b.onclick=()=>{c.drink=b.dataset.drink;persist();draw()});$('#game').querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{$('#game').querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));for(const [mode,id] of [['quiet','cafeQuiet'],['chat','cafeChat'],['focus','cafeFocus']])$('#'+id).hidden=mode!==b.dataset.mode});
const lines={day:['阿電：今天先不用交出漂亮的成績，飲料喝完再說。','小花：那就休息一局！我先把「努力」的牌蓋起來。','老王：坐吧，這杯慢慢喝。事情可以一件一件做。'],game:['阿電：我還在算下一手，你已經跑去喝咖啡了。','小花：贏的先別走，輸的可以先喝一口，再來一局！','老王：剛才那手牌我記下了，下次不一定讓你喔。'],wish:['阿電：先選一件很小的事，做完就可以收工。','小花：我今天想打破恐龍紀錄，你要不要等會一起挑戰？','老王：我想把這杯喝完，然後讀兩頁書。就這樣也很好。']};function chat(topic){const i=Number($('#cafeNPC').value);let t;if(topic==='story')t=c.visits<3?'再來坐到第 3 天，NPC 就會跟你分享熟客小故事。':[['阿電：開店第一天，我排了三張椅子。小花問：不是一個人嗎？我說，留給以後回來的人。','小花：我本來只想借插座，結果老王每天都問「今天贏了沒」。現在我會先來報戰績。','老王：有人每次都坐角落，我就把那張椅子留著。不用每次聊天，記得你有來就好。'][i]][0];else t=lines[topic][i];$('#cafeConversation').textContent=t}chat('wish');$('#game').querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>chat(b.dataset.topic));$('#cafeNPC').onchange=()=>chat('wish');
const disposeSounds=setupCafeSounds();
function clock(){if(running)remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('#cafeClock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(running&&remaining===0){running=false;clearInterval(interval);interval=null;c.focusMinutes+=Number($('#cafeDuration').value);persist();draw();$('#cafeStart').textContent='再來一段';$('#cafeDuration').disabled=false;$('#cafeFocusStatus').textContent='這段時間完成了，喝口水、伸展一下吧 ☕';toast('☕ 這段時間完成了。')}}$('#cafeStart').onclick=()=>{if(running){clock();running=false;clearInterval(interval);interval=null;$('#cafeStart').textContent='繼續';$('#cafeFocusStatus').textContent='暫停中，想繼續再按一下。'}else{if(!remaining)remaining=Number($('#cafeDuration').value)*60;deadline=Date.now()+remaining*1000;running=true;$('#cafeDuration').disabled=true;$('#cafeStart').textContent='暫停';$('#cafeFocusStatus').textContent='老王：你忙你的，我在這裡。';interval=setInterval(clock,250);clock()}};function reset(){running=false;clearInterval(interval);interval=null;remaining=Number($('#cafeDuration').value)*60;$('#cafeDuration').disabled=false;$('#cafeStart').textContent='開始';$('#cafeFocusStatus').textContent='讀書、工作或休息，做你自己的事。';clock()}$('#cafeReset').onclick=reset;$('#cafeDuration').onchange=reset;$('#cafeBack').onclick=closeGame;cleanup=()=>{disposeWeather();clearInterval(interval);disposeSounds()};}
$('#visitCafe').onclick=openCafe;
let cafeLocalWeather=null;
function cafeWeatherKind(code){if(code===0)return ['clear','晴朗','☀️'];if(code>=1&&code<=3)return ['cloud','多雲','☁️'];if(code===45||code===48)return ['fog','有霧','🌫️'];if([71,73,75,77,85,86].includes(code))return ['snow','下雪','❄️'];if(code>=95)return ['storm','雷雨','⛈️'];if([51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return ['rain','下雨','🌧️'];return ['unknown','天氣資料暫缺','🪟']}
function cafeWindowLine(){if(!cafeLocalWeather)return '窗外有什麼天氣，都可以在這裡坐一下。';const w=cafeLocalWeather;if(!w.day&&w.kind==='clear')return '窗外是晴朗的夜晚，留盞燈陪你坐坐。';return {clear:'窗外陽光正好，喝口飲料再出發。',cloud:'雲慢慢走，你也可以慢慢來。',fog:'窗外有點霧，手邊的飲料還暖著。',snow:'窗外下著雪，今天在店裡暖暖待著。',storm:'窗外有雷雨，先留在這裡坐一下吧。',rain:'窗外的雨不急，你也不用急。',unknown:'窗外有什麼天氣，都可以在這裡坐一下。'}[w.kind]}
function setupCafeWeather(draw){let alive=true,controller=null,seq=0,location=cafeLocalWeather?.location||state.cafe.weatherCity||null;function status(t){if(alive)$('#cafeWeatherStatus').textContent=t}async function json(url,signal){const r=await fetch(url,{signal});if(!r.ok)throw Error('network');return r.json()}function render(){if(!alive||!cafeLocalWeather)return;const w=cafeLocalWeather;$('#cafeWeather').dataset.weather=w.kind;$('#cafeWeather').dataset.day=w.day?'day':'night';$('#cafeWeatherTitle').textContent=toTraditional(w.location.name)+' · '+(w.day?w.icon:'🌙')+' '+w.label+' · '+Math.round(w.temp)+'°C';status('更新於 '+new Date(w.fetched).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})+' · '+(w.day?'白天':'夜晚'));draw()}
async function load(loc){location=loc;const request=++seq;if(controller)controller.abort();controller=new AbortController();const control=controller,timeout=setTimeout(()=>control.abort(),12000);status('正在取得當地天氣…');$('#cafeWeatherRefresh').disabled=false;try{const u=new URL('https://api.open-meteo.com/v1/forecast');u.search=new URLSearchParams({latitude:loc.lat,longitude:loc.lon,current:'temperature_2m,weather_code,is_day',timezone:'auto'});const d=await json(u,control.signal);if(!alive||request!==seq)return;const cur=d.current;if(!cur||!Number.isFinite(cur.temperature_2m)||!Number.isFinite(cur.weather_code))throw Error();const [kind,label,icon]=cafeWeatherKind(cur.weather_code);cafeLocalWeather={location:loc,kind,label,icon,temp:cur.temperature_2m,day:cur.is_day===1,fetched:Date.now()};render()}catch{if(alive&&request===seq){cafeLocalWeather=null;$('#cafeWeather').dataset.weather='unknown';$('#cafeWeatherTitle').textContent='天氣暫時無法取得';status('請稍後按「更新天氣」，或搜尋其他城市。');draw()}}finally{clearTimeout(timeout)}}
$('#cafeLocate').onclick=()=>{if(!navigator.geolocation){status('瀏覽器不支援定位，請搜尋城市。');return}status('等待位置授權…');navigator.geolocation.getCurrentPosition(p=>{if(!alive)return;delete state.cafe.weatherCity;persist();load({name:'目前位置附近',lat:Number(p.coords.latitude.toFixed(2)),lon:Number(p.coords.longitude.toFixed(2))})},e=>status(e.code===1?'未允許定位，可以改用城市搜尋。':'無法取得位置，可以改用城市搜尋。'),{enableHighAccuracy:false,timeout:10000,maximumAge:300000})};$('#cafeWeatherRefresh').onclick=()=>{if(location)load(location)};
$('#cafeCityForm').onsubmit=async e=>{e.preventDefault();const name=$('#cafeCity').value.trim();if(name.length<2){status('請輸入至少兩個字的城市名稱。');return}const request=++seq;if(controller)controller.abort();controller=new AbortController();const control=controller,timeout=setTimeout(()=>control.abort(),12000);$('#cafeCityResults').replaceChildren();status('搜尋城市中…');try{const u=new URL('https://geocoding-api.open-meteo.com/v1/search');u.search=new URLSearchParams({name,count:5,language:'zh',format:'json'});const data=await json(u,control.signal);if(!alive||request!==seq)return;if(!data.results?.length){status('找不到城市，試試較大的城市或英文名稱。');return}status('請選擇你的城市：');for(const city of data.results){if(!Number.isFinite(city.latitude)||!Number.isFinite(city.longitude))continue;const b=document.createElement('button');b.type='button';b.textContent=toTraditional([city.name,city.admin1,city.country].filter(Boolean).join(' · '));b.onclick=()=>{const loc={name:b.textContent,lat:city.latitude,lon:city.longitude};state.cafe.weatherCity=loc;persist();$('#cafeCityResults').replaceChildren();load(loc)};$('#cafeCityResults').appendChild(b)}}catch{if(alive&&request===seq)status('城市搜尋暫時無法使用，請稍後再試。')}finally{clearTimeout(timeout)}};
if(cafeLocalWeather)render();if(location&&(!cafeLocalWeather||Date.now()-cafeLocalWeather.fetched>600000))load(location);else if(location)$('#cafeWeatherRefresh').disabled=false;const refresh=setInterval(()=>{if(alive&&location&&!document.hidden)load(location)},600000);return ()=>{alive=false;seq++;clearInterval(refresh);if(controller)controller.abort()}}
